__NUXT_JSONP__("/sp/how-to-apply", {data:[{details:{slug:"sp",pageTitle:"¿Qué tipo de visa tienes previsto aplicar? | Mentor Language Institute",pageDescription:"Por favor, elija su situación de visa de las siguientes opciones",title:"¿Qué tipo de visa tienes previsto aplicar?",image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fvisa.jpg",category:[{title:"Por favor, elija su situación de visa de las siguientes opciones:",btn_visa:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fvisa_btn-sp.png",link:"\u002Fsp\u002Fhow-to-apply\u002Fstudent-visa-f1"},btn_others:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fothers_btn-sp.png",link:"\u002Fsp\u002Fhow-to-apply\u002Fothers"}}],content:{subtitle:"¿Alguna pregunta?",description:["Normalmente, necesitarás una visa de estudiante para permanecer como estudiante a largo plazo en los Estados Unidos. \u003Cbr \u002F\u003E Si no sabes si necesitas una visa o no, contáctenos.","Ofrecemos asistencia en 8 idiomas diferentes."],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fcontact-us-sp.jpg",link:"\u002Fsp\u002Fcontact"}},dir:"\u002Fhow-to-apply",path:"\u002Fhow-to-apply\u002Fsp",extension:".json",createdAt:"2026-10-22T16:31:29.656Z",updatedAt:"2025-05-26T12:06:27.791Z"}}],fetch:{},mutations:void 0});